arguments.content:
:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --link: #002EAD;
  --bg-color: #f5f6f7;
  --text-dark: #333;
  --text-light: #fff;
  --border: #ddd;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Inter', system-ui, sans-serif; background-color: var(--bg-color); color: var(--text-dark); line-height: 1.6; }
a { text-decoration: none; color: inherit; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 1rem; }

/* Header */
.site-header { background-color: var(--primary); color: var(--text-light); padding: 1rem 0; }
.site-header .container { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; }
.logo { font-size: 1.5rem; font-weight: bold; }
.search-bar { flex: 1; margin: 0 2rem; min-width: 250px; }
.search-bar input { width: 100%; padding: 0.5rem 1rem; border-radius: 4px; border: none; background: #22223b; color: #fff; }
.search-bar input::placeholder { color: #aaa; }
.nav-links { display: flex; gap: 1.5rem; align-items: center; }
.nav-links a:hover { color: var(--accent); }
.hamburger { display: none; background: none; border: none; color: #fff; font-size: 1.5rem; cursor: pointer; }

/* Mobile Menu */
.mobile-menu { display: none; background-color: var(--primary); padding: 1rem; }
.mobile-menu.active { display: block; }
.mobile-menu a { display: block; padding: 0.5rem 0; color: #fff; border-bottom: 1px solid #333; }
.mobile-menu a:last-child { border-bottom: none; }

/* Banner */
.banner { background-color: #eee; text-align: center; padding: 0.5rem; font-size: 0.9rem; border-bottom: 1px solid var(--border); }
.banner a { color: var(--text-dark); text-decoration: underline; }

/* Main Content */
.main-content { padding: 3rem 0; }

/* Section Titles */
.section-title { font-size: 1.8rem; margin-bottom: 1.5rem; color: var(--primary); border-bottom: 2px solid var(--primary); display: inline-block; padding-bottom: 0.5rem; }

/* Article Card */
.article-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 2rem; margin-top: 2rem; }
.article-card { background: #fff; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 5px rgba(0,0,0,0.05); transition: transform 0.2s; display: flex; flex-direction: column; border: 1px solid var(--border); }
.article-card:hover { transform: translateY(-5px); box-shadow: 0 4px 10px rgba(0,0,0,0.1); }
.article-thumb { height: 180px; background: #e0e0e0; position: relative; }
.article-thumb img { width: 100%; height: 100%; object-fit: cover; }
.article-content { padding: 1.5rem; display: flex; flex-direction: column; flex: 1; }
.article-tag { align-self: flex-start; background: #eee; padding: 0.2rem 0.6rem; border-radius: 4px; font-size: 0.8rem; font-weight: 600; margin-bottom: 1rem; text-transform: uppercase; color: var(--primary); transition: background 0.2s, color 0.2s; }
.article-tag:hover { background: var(--primary); color: #fff; }
.article-title { font-size: 1.25rem; font-weight: bold; margin-bottom: 1.5rem; color: var(--primary); line-height: 1.4; }
.article-meta { margin-top: auto; display: flex; align-items: center; gap: 0.75rem; font-size: 0.85rem; color: #666; }
.author-avatar { width: 32px; height: 32px; border-radius: 50%; background: #ccc; }
.author-info { display: flex; flex-direction: column; }
.author-name { font-weight: bold; color: var(--text-dark); }
.article-card.hidden { display: none; }

/* Featured Article */
.featured-article { background: #fff; border-radius: 8px; overflow: hidden; margin-bottom: 3rem; display: grid; grid-template-columns: 1fr 1fr; box-shadow: 0 2px 5px rgba(0,0,0,0.05); border: 1px solid var(--border); }
.featured-article .article-thumb { height: auto; min-height: 300px; }
.featured-article .article-content { padding: 3rem; justify-content: center; }
.featured-article .article-title { font-size: 2rem; }

/* Buttons */
.btn { display: inline-block; padding: 0.75rem 1.5rem; background: var(--accent); color: var(--primary); font-weight: bold; border: none; border-radius: 4px; cursor: pointer; text-align: center; transition: background 0.2s; }
.btn:hover { background: #e59a2a; }
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: #1a1a3a; }
.btn-outline { background: transparent; border: 2px solid var(--primary); color: var(--primary); }
.btn-outline:hover { background: var(--primary); color: #fff; }
.btn-block { display: block; width: 100%; }
.load-more { text-align: center; margin-top: 3rem; }

/* Tags Scroll */
.tag-header { margin-bottom: 1rem; }
.tags-scroll { display: flex; gap: 1rem; overflow-x: auto; padding-bottom: 1rem; margin-bottom: 2rem; scrollbar-width: none; }
.tags-scroll::-webkit-scrollbar { display: none; }
.tag-pill { background: #fff; border: 1px solid var(--border); padding: 0.5rem 1rem; border-radius: 20px; white-space: nowrap; font-size: 0.9rem; font-weight: 500; transition: border-color 0.2s; }
.tag-pill:hover { border-color: var(--primary); }
.tag-pill span { color: #888; margin-left: 0.5rem; font-size: 0.8rem; }

/* Curriculum */
.welcome-cta { text-align: center; padding: 2rem; background: #fff; border: 1px solid var(--border); border-radius: 8px; margin-bottom: 3rem; }
.curriculum-list { list-style: none; margin: 2rem 0; }
.curriculum-item { background: #fff; margin-bottom: 1rem; padding: 1.5rem; border-radius: 8px; border: 1px solid var(--border); display: flex; align-items: center; gap: 1rem; font-weight: bold; font-size: 1.1rem; transition: transform 0.2s, box-shadow 0.2s; }
.curriculum-item:hover { transform: translateY(-2px); box-shadow: 0 2px 5px rgba(0,0,0,0.05); }
.curriculum-item::before { content: '📁'; font-size: 1.5rem; }

/* Curriculum Sections */
.learn-section { margin-bottom: 3rem; }

/* Donate Page */
.donate-hero { text-align: center; margin-bottom: 3rem; max-width: 800px; margin-left: auto; margin-right: auto; }
.donate-hero h1 { font-size: 2.5rem; margin-bottom: 1rem; color: var(--primary); }
.donate-grid { display: grid; grid-template-columns: 1fr 400px; gap: 3rem; margin-bottom: 4rem; }
.donate-card { background: #fff; padding: 2rem; border-radius: 8px; box-shadow: 0 4px 15px rgba(0,0,0,0.08); border-top: 5px solid var(--accent); align-self: start; }
.amount-tabs { display: flex; gap: 0.5rem; margin-bottom: 1.5rem; }
.amount-btn { flex: 1; padding: 0.75rem; border: 1px solid var(--primary); background: #fff; color: var(--primary); font-weight: bold; cursor: pointer; border-radius: 4px; font-size: 1.1rem; transition: background 0.2s, color 0.2s; }
.amount-btn:hover { background: #f0f0f0; }
.amount-btn.active { background: var(--primary); color: #fff; }
.donate-text { margin-bottom: 1.5rem; font-size: 0.95rem; text-align: center; color: #555; }
.donate-sub-label { display: block; text-align: center; font-size: 0.8rem; color: #888; margin-top: 1rem; }

/* Lists */
.styled-list { list-style: none; margin-bottom: 2rem; }
.styled-list li { padding: 0.5rem 0; position: relative; padding-left: 1.5rem; }
.styled-list li::before { content: '✓'; position: absolute; left: 0; color: var(--accent); font-weight: bold; }

.stats-list { list-style: none; margin-bottom: 2rem; }
.stats-list li { padding: 0.5rem 0; position: relative; padding-left: 1.5rem; }
.stats-list li::before { content: '•'; position: absolute; left: 0; color: var(--primary); font-weight: bold; font-size: 1.5rem; line-height: 1; top: 0.2rem; }

/* Accordion */
.faq-accordion { margin-top: 2rem; border: 1px solid var(--border); border-radius: 8px; background: #fff; }
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-item:last-child { border-bottom: none; }
.accordion-btn { width: 100%; text-align: left; padding: 1.5rem; background: none; border: none; font-weight: bold; font-size: 1.1rem; cursor: pointer; display: flex; justify-content: space-between; align-items: center; color: var(--primary); }
.accordion-btn::after { content: '+'; font-size: 1.5rem; font-weight: normal; color: #888; }
.accordion-btn[aria-expanded="true"]::after { content: '−'; }
.accordion-content { padding: 0 1.5rem 1.5rem; display: none; color: #555; line-height: 1.6; }
.accordion-content.active { display: block; }

/* Footer */
.site-footer { background: var(--primary); color: #fff; padding: 4rem 0 2rem; margin-top: 4rem; font-size: 0.9rem; }
.footer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; margin-bottom: 2rem; }
.footer-links { display: flex; flex-wrap: wrap; gap: 1rem; justify-content: center; border-top: 1px solid #333; padding-top: 2rem; }
.footer-links a { color: #aaa; }
.footer-links a:hover { color: #fff; }
.mission { color: #ccc; }
.trending { margin-top: 1rem; color: #aaa; }

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: block; }
  .search-bar { order: 3; width: 100%; margin: 1rem 0 0; }
  .featured-article { grid-template-columns: 1fr; }
  .donate-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .donate-hero h1 { font-size: 2rem; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const hamburger = document.querySelector('.hamburger');
  const mobileMenu = document.querySelector('.mobile-menu');
  if (hamburger && mobileMenu) {
    hamburger.addEventListener('click', () => {
      mobileMenu.classList.toggle('active');
    });
  }

  // Donate Amount Tabs
  const amountBtns = document.querySelectorAll('.amount-btn');
  const donateText = document.querySelector('#dynamic-donate-text');
  const donateBtnLabel = document.querySelector('#donate-btn-label');

  if (amountBtns.length > 0 && donateText) {
    amountBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        amountBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const amount = parseInt(btn.dataset.amount, 10);
        const hours = amount * 50; // Based on $20 = 1000 hours
        donateText.textContent = `Your $${amount} donation will provide ${hours.toLocaleString()} hours of learning to people around the world each month.`;
        if(donateBtnLabel) {
          donateBtnLabel.textContent = `Donating $${amount} / month: edit amount · Secure donation`;
        }
      });
    });
  }

  // FAQ Accordion
  const accordionBtns = document.querySelectorAll('.accordion-btn');
  if (accordionBtns.length > 0) {
    accordionBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const content = btn.nextElementSibling;
        const isActive = content.classList.contains('active');

        // Close all
        document.querySelectorAll('.accordion-content').forEach(c => c.classList.remove('active'));
        document.querySelectorAll('.accordion-btn').forEach(b => b.setAttribute('aria-expanded', 'false'));

        if (!isActive) {
          content.classList.add('active');
          btn.setAttribute('aria-expanded', 'true');
        }
      });
    });
  }

  // Load More Articles
  const loadMoreBtn = document.querySelector('#load-more-btn');
  const hiddenArticles = document.querySelectorAll('.article-card.hidden');
  if (loadMoreBtn && hiddenArticles.length > 0) {
    loadMoreBtn.addEventListener('click', () => {
      hiddenArticles.forEach(card => card.classList.remove('hidden'));
      loadMoreBtn.style.display = 'none'; // hide button after loading
    });
  }
});
